#include "project_backup.h"
#include <windows.h>
#include <algorithm>
#include <atomic>
#include <chrono>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <mutex>
#include <sstream>
#include <thread>
namespace moon::project {
namespace {
std::uint64_t nowMs(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
std::uint64_t modifiedMs(const std::filesystem::path& p){WIN32_FILE_ATTRIBUTE_DATA info{};if(!GetFileAttributesExW(p.c_str(),GetFileExInfoStandard,&info))throw std::runtime_error("Cannot read backup timestamp");ULARGE_INTEGER v;v.LowPart=info.ftLastWriteTime.dwLowDateTime;v.HighPart=info.ftLastWriteTime.dwHighDateTime;return v.QuadPart<116444736000000000ULL?0:(v.QuadPart-116444736000000000ULL)/10000;}
bool plain(const std::filesystem::path& p){const auto attributes=GetFileAttributesW(p.c_str());return attributes!=INVALID_FILE_ATTRIBUTES&&!(attributes&FILE_ATTRIBUTE_REPARSE_POINT);}
BackupRecord record(const std::filesystem::path& p){return {p,modifiedMs(p),std::filesystem::file_size(p)};}
std::string lower(std::string v){for(auto& c:v)if(c>='A'&&c<='Z')c+=32;return v;}
void appendProject(std::vector<BackupRecord>& out,const std::filesystem::path& p){if(!std::filesystem::is_directory(p)||!plain(p))return;for(const auto& e:std::filesystem::directory_iterator(p))if(e.is_regular_file()&&plain(e.path())&&lower(e.path().extension().u8string())==".moonsprite")out.push_back(record(e.path()));}
std::mutex jobsMutex;std::map<std::filesystem::path,BackupPolicy> jobs;bool running=false;
}
BackupPolicy normalizeBackupPolicy(BackupPolicy p){p.versions=std::clamp(p.versions,1,10);p.days=std::clamp(p.days,1,365);return p;}
std::string backupPathHash(const std::filesystem::path& p){std::uint64_t hash=0xcbf29ce484222325ULL;for(unsigned char c:p.u8string())hash=(hash^c)*0x100000001b3ULL;std::ostringstream out;out<<std::hex<<std::setfill('0')<<std::setw(16)<<hash;return out.str();}
std::filesystem::path backupProjectDirectory(const std::filesystem::path& p){std::u32string name;for(char32_t c:p.stem().u32string()){WORD kind=0;const wchar_t w=wchar_t(c);const bool alpha=c<=0xffff&&GetStringTypeW(CT_CTYPE1,&w,1,&kind)&&(kind&(C1_ALPHA|C1_DIGIT));if(alpha||c==U'-'||c==U'_'){name.push_back(c);if(name.size()==64)break;}}if(name.empty())name=U"project";const auto hash=backupPathHash(p);return std::filesystem::path(name+U"-"+std::u32string(hash.begin(),hash.end()));}
std::vector<BackupRecord> listProjectBackups(const std::filesystem::path& project,const std::filesystem::path& root){if(lower(project.extension().u8string())!=".moonsprite")throw std::invalid_argument("只能回档已保存的 .moonsprite 工程。");std::vector<BackupRecord> out;const auto key=backupProjectDirectory(project);appendProject(out,root/"native-v1"/key);appendProject(out,root/key);if(std::filesystem::is_directory(root)){const auto hash=backupPathHash(project);const std::string suffix=".moonsprite.bak";for(const auto& e:std::filesystem::directory_iterator(root)){const auto name=e.path().filename().u8string();if(!e.is_regular_file()||!plain(e.path()))continue;if(name==hash+suffix||(name.rfind(hash+"-",0)==0&&name.size()>=suffix.size()&&name.substr(name.size()-suffix.size())==suffix))out.push_back(record(e.path()));}}std::stable_sort(out.begin(),out.end(),[](const auto& a,const auto& b){return a.modifiedMs>b.modifiedMs;});return out;}
void createCommittedProjectBackup(const std::filesystem::path& project,const BackupPolicy& raw){auto p=normalizeBackupPolicy(raw);if(!p.enabled||lower(project.extension().u8string())!=".moonsprite"||!std::filesystem::is_regular_file(project))return;if(p.directory.empty())throw std::invalid_argument("Empty project backup root");const auto directory=p.directory/"native-v1"/backupProjectDirectory(project);std::filesystem::create_directories(directory);if(!plain(directory)||!plain(directory.parent_path()))throw std::runtime_error("Backup directory cannot be a link");static std::atomic<unsigned> serial{0};const auto suffix=std::to_string(nowMs())+"-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(++serial);const auto backup=directory/("backup-"+suffix+".moonsprite"),pending=directory/("backup-"+suffix+".pending");try{if(!CreateHardLinkW(pending.c_str(),project.c_str(),nullptr)&&!CopyFileW(project.c_str(),pending.c_str(),TRUE))throw std::runtime_error("Cannot preserve committed project backup (Windows "+std::to_string(GetLastError())+")");if(!MoveFileExW(pending.c_str(),backup.c_str(),MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Cannot publish committed project backup");}catch(...){DeleteFileW(pending.c_str());throw;}}
std::vector<std::filesystem::path> planBackupPrune(std::vector<BackupCandidate> values,std::uint64_t now,int versions,int days){std::stable_sort(values.begin(),values.end(),[](const auto& a,const auto& b){return a.record.modifiedMs>b.record.modifiedMs;});versions=std::clamp(versions,1,10);days=std::clamp(days,1,365);std::uint64_t retainedBytes=0;std::map<std::string,int> retained;std::vector<std::filesystem::path> remove;for(std::size_t i=0;i<values.size();++i){const auto& c=values[i];const bool expired=now>c.record.modifiedMs&&now-c.record.modifiedMs>std::uint64_t(days)*86400000;const bool overSize=c.record.size>512ULL*1024*1024||retainedBytes>512ULL*1024*1024-c.record.size;if(i>0&&(expired||i>=50||retained[c.projectKey]>=versions||overSize)){remove.push_back(c.record.path);continue;}retainedBytes+=c.record.size;++retained[c.projectKey];}return remove;}
void scheduleNativeBackupPrune(BackupPolicy p){p=normalizeBackupPolicy(p);{std::lock_guard<std::mutex> guard(jobsMutex);jobs[p.directory]=p;if(running)return;running=true;}try{std::thread([]{for(;;){BackupPolicy p;{std::lock_guard<std::mutex> guard(jobsMutex);if(jobs.empty()){running=false;return;}p=jobs.begin()->second;jobs.erase(jobs.begin());}try{const auto root=p.directory/"native-v1";if(!std::filesystem::is_directory(root)||!plain(root))continue;std::vector<BackupCandidate> values;for(const auto& group:std::filesystem::directory_iterator(root)){if(!group.is_directory()||!plain(group.path()))continue;for(const auto& file:std::filesystem::directory_iterator(group.path())){const auto name=file.path().filename().u8string();if(file.is_regular_file()&&plain(file.path())&&name.rfind("backup-",0)==0&&file.path().extension()==L".moonsprite")values.push_back({record(file.path()),group.path().filename().u8string()});}}for(const auto& file:planBackupPrune(std::move(values),nowMs(),p.versions,p.days)){if(file.parent_path().parent_path()!=root||!plain(file)||!plain(file.parent_path()))throw std::runtime_error("Backup prune ownership changed");std::filesystem::remove(file);}}catch(const std::exception& e){std::cerr<<"Project backup cleanup failed: "<<e.what()<<'\n';}}}).detach();}catch(...){std::lock_guard<std::mutex> guard(jobsMutex);running=false;throw;}}
}
